import XCTest
import PrismCore
import AVFoundation
@testable import TogetherPoC

final class AV1SoftwarePlaybackTests:XCTestCase {
 @MainActor func testTenBitAV1UsesSoftwareRendererAndRoomAdapter() async throws {
  // Three seconds of synthetic 10-bit video, with keyframes every second.
  let data=try XCTUnwrap(Data(base64Encoded:""))
  let file=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString+".mkv")
  try data.write(to:file)
  defer {try? FileManager.default.removeItem(at:file)}
  let model=TestClient(automaticallyConnect:false)
  model.loadMedia(file)
  for _ in 0..<250 {
   if model.adapter.software != nil {break}
   try await Task.sleep(nanoseconds:20_000_000)
  }
  let pipeline=try XCTUnwrap(model.adapter.software,model.requestStatus)
  defer {if model.adapter.software != nil {model.handleBackground()}}
  XCTAssertNotNil(model.softwarePicture)
  XCTAssertNotNil(pipeline.sourceInfo?.video)
  XCTAssertTrue(model.adapter.ready)
  XCTAssertGreaterThan(model.adapter.duration,2500)
  model.adapter.play()
  for _ in 0..<100 {
   if model.adapter.position>200 {break}
   try await Task.sleep(nanoseconds:20_000_000)
  }
  XCTAssertGreaterThan(model.adapter.position,200)
  model.adapter.pause()
  model.adapter.seekTo(1800)
  for _ in 0..<150 {
   if !model.adapter.isSeeking && abs(model.adapter.position-1800)<250 {break}
   try await Task.sleep(nanoseconds:20_000_000)
  }
  XCTAssertEqual(model.adapter.position,1800,accuracy:250)
  XCTAssertFalse(model.adapter.isSeeking)
  model.playback.refresh()
  XCTAssertEqual(model.playback.position,model.adapter.position/1000,accuracy:0.1)
  model.handleBackground()
  XCTAssertNil(model.adapter.software)
  XCTAssertNil(model.softwarePicture)
 }
}
